static void text5(int x,int y,const char*t,int s,uint16_t col){while(*t){char ch=*t++;if(ch==' '){x+=4*s;continue;}int id=-1;if(ch>='A'&&ch<='Z')id=ch-'A';else if(ch>='a'&&ch<='z')id=ch-'a';if(id>=0)for(int cx=0;cx<5;cx++)for(int cy=0;cy<7;cy++)if(ALPHA[id][cx]&(1<<cy))rect(x+cx*s,y+cy*s,s,s,col);x+=6*s;}}
static void fmtLap(uint32_t ms,char*out,size_t n){uint32_t m=ms/60000u;ms%=60000u;snprintf(out,n,"%02lu:%02lu.%03lu",(unsigned long)m,(unsigned long)(ms/1000u),(unsigned long)(ms%1000u));}
static void fmtDelta(int32_t ms,char*out,size_t n){char sign=ms<=0?'-':'+';uint32_t a=(uint32_t)(ms<0?-ms:ms);snprintf(out,n,"%c%lu.%03lu",sign,(unsigned long)(a/1000u),(unsigned long)(a%1000u));}
static void saveRaceBox(const String&a){prefs.begin("proot",false);prefs.putString("rbAddr",a);prefs.end();savedRbAddr=a;}
