static bool probeRaceBoxIndex(int idx){if(idx<0||idx>=raceboxCount)return false;String addr=raceboxAddr[idx];NimBLEAddress target(std::string(addr.c_str()),raceboxAddrType[idx]);NimBLEClient*stale=NimBLEDevice::getClientByPeerAddress(target);if(stale)NimBLEDevice::deleteClient(stale);NimBLEClient*client=NimBLEDevice::createClient();if(!client||!client->connect(target)){if(client)NimBLEDevice::deleteClient(client);return false;}NimBLERemoteService*svc=client->getService("6E400001-B5A3-F393-E0A9-E50E24DCCA9E");if(!svc){client->disconnect();NimBLEDevice::deleteClient(client);return false;}rbRx=svc->getCharacteristic("6E400002-B5A3-F393-E0A9-E50E24DCCA9E");rbTx=svc->getCharacteristic("6E400003-B5A3-F393-E0A9-E50E24DCCA9E");if(!rbRx||!rbTx||!rbTx->canNotify()||!rbTx->subscribe(true,RaceBox::notify)){client->disconnect();NimBLEDevice::deleteClient(client);rbRx=rbTx=nullptr;return false;}rbClient=client;rbConnected=true;connectedAddr=addr;RaceBox::setConnection(client,rbRx,true);saveRaceBox(addr);return true;}
