static bool readTouch(int&lx,int&ly){uint8_t cmd[8]={0xb5,0xab,0xa5,0x5a,0,0,0,8},b[14]={0};Wire.beginTransmission(TOUCH_ADDR);Wire.write(cmd,8);if(Wire.endTransmission()!=0)return false;if(Wire.requestFrom(TOUCH_ADDR,14)!=(size_t)14)return false;Wire.readBytes(b,14);if(!b[1]||b[0])return false;int nx=((b[2]&15)<<8)|b[3],ny=((b[4]&15)<<8)|b[5];lx=constrain(639-nx,0,639);ly=constrain(179-ny,0,179);return true;}
static void drawLastDevicePrompt(){uint16_t black=C(0),white=C(0xFFFF),green=C(0x07E0),red=C(0xF800),gray=C(0x4208);for(size_t i=0;i<180u*640u;i++)screen[i]=black;text5(92,22,"CONNECT TO LAST DEVICE",3,white);if(savedRaceboxIndex>=0){String id="";for(int k=0;k<raceboxes[savedRaceboxIndex].length();k++)if(isDigit(raceboxes[savedRaceboxIndex][k]))id+=raceboxes[savedRaceboxIndex][k];if(id.length()>10)id=id.substring(id.length()-10);if(id.length())num(248,62,id.c_str(),3,gray);}rect(70,108,220,54,green);text5(145,122,"YES",4,black);rect(350,108,220,54,red);text5(435,122,"NO",4,white);present();}
static void drawRaceBoxList(){uint16_t black=C(0),white=C(0xFFFF),green=C(0x07E0),gray=C(0x4208),red=C(0xF800),dark=C(0x2104);for(size_t i=0;i<180u*640u;i++)screen[i]=black;int pages=max(1,(raceboxCount+2)/3);if(listPage>=pages)listPage=pages-1;int first=listPage*3;for(int row=0;row<3;row++){int i=first+row,y=18+row*50;if(i>=raceboxCount)break;uint16_t col=gray;if(i==selectedRacebox){if(connState==CONN_WORKING)col=C(0xFFE0);else if(connState==CONN_OK&&rbConnected)col=green;else if(connState==CONN_FAIL)col=red;}rect(12,y,300,38,col);num(22,y+7,String(i+1).c_str(),3,black);}rect(390,12,190,42,dark);text5(447,22,"UP",3,white);rect(390,126,190,42,dark);text5(447,136,"DN",3,white);present();}
